BEGIN;SET LOCAL statement_timeout='30s';
DO $$ DECLARE native uuid;actor uuid;org uuid:=gen_random_uuid();foreign_org uuid:=gen_random_uuid();profile_id uuid:=gen_random_uuid();brand uuid;foreign_brand uuid:=gen_random_uuid();contract uuid;sale uuid;request uuid;r jsonb;ledger jsonb;n int;
BEGIN
 SELECT target_user_id,source_user_id INTO native,actor FROM tj.source_user_identity_map i WHERE identity_verified AND activation_status='activated' AND NOT EXISTS(SELECT 1 FROM tj.platform_admins a WHERE a.user_id=i.source_user_id) LIMIT 1;
 IF native IS NULL THEN RAISE EXCEPTION 'No fixture actor';END IF;
 INSERT INTO tj.organizations(id,name,slug) VALUES(org,'Rollback MDF',org::text),(foreign_org,'Rollback foreign MDF',foreign_org::text);
 INSERT INTO tj.organization_members(organization_id,user_id,role,status) VALUES(org,actor,'owner','active');
 INSERT INTO tj.mdf_organizations(id,organization_id,name,owner_email) VALUES(org,org,'Rollback MDF','mdf-fixture@example.invalid');
 INSERT INTO tj.mdf_platform_users(id,organization_id,org_id,source_user_id,email,display_name,role,is_active) VALUES(profile_id,org,org,actor,'mdf-fixture@example.invalid','Fixture user','super_admin',true);
 INSERT INTO tj.mdf_brands(id,organization_id,brand_name) VALUES(foreign_brand,foreign_org,'Foreign fixture');
 PERFORM set_config('request.jwt.claim.sub',native::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',native,'email','spoof@example.invalid')::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.tj_runtime_mdf_tracker('context');IF r->>'organization_id'<>org::text OR r->'profile'->>'role'<>'super_admin' THEN RAISE EXCEPTION 'Context binding failed';END IF;
 IF jsonb_array_length(public.tj_runtime_mdf_tracker('read','mdf_brands'))<>0 THEN RAISE EXCEPTION 'Foreign catalog exposed';END IF;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('read','mdf_email_queue');RAISE EXCEPTION 'Queue exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('read','mdf_brands',NULL,'{}','{"order":"id;select 1"}');RAISE EXCEPTION 'Unsafe order accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'unsupported_order' THEN RAISE;END IF;END;
 r:=public.tj_runtime_mdf_tracker('insert','mdf_brands',NULL,'{"brand_name":"Rollback brand"}');brand:=(r->0->>'id')::uuid;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('insert','mdf_brands',NULL,jsonb_build_object('brand_name','Spoof','organization_id',foreign_org));RAISE EXCEPTION 'Tenant spoof accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'protected_or_unknown_field%' THEN RAISE;END IF;END;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('update','mdf_brands',foreign_brand,'{"brand_name":"Spoof"}');RAISE EXCEPTION 'Foreign update accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.tj_runtime_mdf_tracker('insert','mdf_brand_contracts',NULL,jsonb_build_object('brand_id',brand,'effective_date','2026-01-01','contract_expiry_date','2026-12-31','coop_enabled',true,'coop_includes_accessories',true,'coop_pct',3,'vr_enabled',true,'vr_base_pct',2));contract:=(r->0->>'id')::uuid;
 r:=public.tj_runtime_mdf_tracker('insert','mdf_sales_data',NULL,jsonb_build_object('brand_id',brand,'period_start','2026-09-01','period_end','2026-09-30','gross_sales',1000,'returns_allowances',100,'product_sales',900));sale:=(r->0->>'id')::uuid;
 IF (r->0->>'net_sales')::numeric<>900 THEN RAISE EXCEPTION 'Net sales evidence failed';END IF;
 ledger:=public.tj_runtime_mdf_tracker('read','mdf_coop_ledger');IF jsonb_array_length(ledger)<>1 OR (ledger->0->>'amount')::numeric<>27 OR ledger->0->>'reference_id'<>sale::text THEN RAISE EXCEPTION 'Atomic co-op accrual failed';END IF;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('update','mdf_coop_ledger',(ledger->0->>'id')::uuid,'{"amount":999}');RAISE EXCEPTION 'Recorded accrual overwritten';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('update','mdf_sales_data',sale,'{"gross_sales":999}');RAISE EXCEPTION 'Source sales overwritten';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.tj_runtime_mdf_tracker('insert','mdf_sales_data',NULL,jsonb_build_object('brand_id',brand,'period_start','2026-10-01','period_end','2026-10-31','gross_sales',100,'returns_allowances',100,'product_sales',0));IF (r->0->>'net_sales')::numeric<>0 THEN RAISE EXCEPTION 'Zero lost';END IF;
 r:=public.tj_runtime_mdf_tracker('insert','mdf_vr_calculations',NULL,jsonb_build_object('brand_id',brand,'contract_id',contract,'period_start','2026-09-01','period_end','2026-10-31','eligible_sales',99999,'rebate_pct',99,'rebate_amount',99999));IF (r->0->>'rebate_amount')::numeric<>18 OR (r->0->>'eligible_sales')::numeric<>900 OR r->0->>'status'<>'calculated' THEN RAISE EXCEPTION 'Server rebate evidence failed';END IF;
 IF jsonb_array_length(public.tj_runtime_mdf_tracker('read','mdf_coop_ledger'))<>1 THEN RAISE EXCEPTION 'Zero sales accrued';END IF;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('insert','mdf_sales_data',NULL,jsonb_build_object('brand_id',foreign_brand,'period_start','2026-09-01','period_end','2026-09-30','gross_sales',10));RAISE EXCEPTION 'Foreign brand sale accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.tj_runtime_mdf_tracker('insert','mdf_coop_requests',NULL,jsonb_build_object('title','Rollback request','request_type','event','brand_ids',jsonb_build_array(brand),'estimated_cost',0,'event_date','','submitted_by','Spoof','submitted_by_email','spoof@example.invalid','submitted_by_role','viewer'));request:=(r->0->>'id')::uuid;
 IF r->0->>'submitted_by'<>'Fixture user' OR r->0->>'status'<>'submitted' OR r->0->>'event_date' IS NOT NULL OR (r->0->>'estimated_cost')::numeric<>0 THEN RAISE EXCEPTION 'Request evidence failed';END IF;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('update','mdf_coop_requests',request,'{"status":"approved","marketing_decision":"approved"}');RAISE EXCEPTION 'Approval bypass accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.tj_runtime_mdf_tracker('update','mdf_coop_requests',request,'{"status":"marketing_review","manager_decision":"approved","manager_reviewed_by":"Spoof"}');
 r:=public.tj_runtime_mdf_tracker('update','mdf_coop_requests',request,'{"status":"approved","marketing_decision":"approved","marketing_reviewed_by":"Spoof"}');IF r->0->>'marketing_reviewed_by'<>'Fixture user' THEN RAISE EXCEPTION 'Review actor spoofed';END IF;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('update','mdf_coop_requests',request,'{"status":"denied","marketing_decision":"denied"}');RAISE EXCEPTION 'Finalized request overwritten';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'request_already_finalized' THEN RAISE;END IF;END;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('delete','mdf_brands',brand);RAISE EXCEPTION 'Source deleted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('insert','mdf_platform_users',NULL,'{"email":"attacker@example.invalid","role":"super_admin"}');RAISE EXCEPTION 'Email access grant accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM tj.mdf_audit_log WHERE organization_id=org AND entity_id=request AND details->>'native_user_id'=native::text) THEN RAISE EXCEPTION 'Atomic audit missing';END IF;
 UPDATE tj.mdf_platform_users SET role='viewer' WHERE id=profile_id;
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.tj_runtime_mdf_tracker('insert','mdf_brands',NULL,'{"brand_name":"Viewer spoof"}');RAISE EXCEPTION 'Viewer wrote';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tj_runtime_mdf_tracker('read','mdf_audit_log');RAISE EXCEPTION 'Viewer read admin audit';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';UPDATE tj.organization_members SET status='suspended' WHERE organization_id=org AND user_id=actor;EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.tj_runtime_mdf_tracker('context');RAISE EXCEPTION 'Suspended member admitted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.proname IN ('mdf_tracker','tj_runtime_mdf_tracker') AND has_function_privilege('anon',p.oid,'execute')) THEN RAISE EXCEPTION 'Anon execution exposed';END IF;
END $$;
ROLLBACK;
